# structtest.Inner3
Structtest_Inner3_new <- function(...) {
  args <- list(...)
  out <- list()
  if (!is.null(args$name)) out$name <- args$name
  if (!is.null(args$value)) out$value <- args$value
  class(out) <- c("pbwire", "list")
  out
}

Structtest_Inner3_encode <- function(msg) {
  pbwire_encode(.pbwire_get_schema(), "structtest.Inner3", msg)
}

Structtest_Inner3_decode <- function(wire) {
  pbwire_decode(.pbwire_get_schema(), "structtest.Inner3", wire)
}

